import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Quick screening of features based on types and simple statistics
    candidate_features = []
    for i, fid in enumerate(feats.ids):
        # Only consider non-clinical features for potential drivers
        if feats.types[i] != 'clinical':
            candidate_features.append(fid)

    # Remove near-duplicates quickly
    final_features = []
    used = set()

    # Simple approach: just take first few features that aren't too correlated
    for i, fid in enumerate(candidate_features):
        if fid in used:
            continue

        # Check correlation with already selected features
        add_fid = True
        for existing_fid in final_features:
            try:
                corr = np.corrcoef(feats.x[:, feats.column(fid)], 
                                  feats.x[:, feats.column(existing_fid)])[0, 1]
                if abs(corr) >= 0.6:
                    add_fid = False
                    break
            except:
                continue

        if add_fid:
            final_features.append(fid)
            used.add(fid)

        # Limit to reasonable number to avoid slow computation
        if len(final_features) >= 20:
            break

    # If no candidates, return empty design
    if not final_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Simple ranking by effect size (difference in means between groups)
    feature_scores = []
    for fid in final_features:
        col_idx = feats.column(fid)
        try:
            y0_mean = np.mean(feats.x[feats.y == 0, col_idx])
            y1_mean = np.mean(feats.x[feats.y == 1, col_idx])
            effect_size = abs(y1_mean - y0_mean)
            feature_scores.append((fid, effect_size))
        except:
            feature_scores.append((fid, 0))

    # Sort by effect size
    feature_scores.sort(key=lambda x: x[1], reverse=True)

    # Top features as drivers
    drivers = tuple([fid for fid, _ in feature_scores[:MAX_DRIVERS]])

    # All features go into model
    columns = tuple(final_features)

    # No interaction terms
    products = ()

    # Simple weighted score
    loadings = {}
    total_weight = 0

    for fid in columns:
        col_idx = feats.column(fid)
        try:
            y0_mean = np.mean(feats.x[feats.y == 0, col_idx])
            y1_mean = np.mean(feats.x[feats.y == 1, col_idx])
            weight = abs(y1_mean - y0_mean)
            loadings[fid] = weight
            total_weight += weight
        except:
            loadings[fid] = 0

    # Normalize
    if total_weight > 0:
        for fid in loadings:
            loadings[fid] /= total_weight

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
